    ('29140e0f-fd88-5896-9fad-c2c3177d699f', '9caabde2-68e9-51d9-88e4-633f118539f8', 'NOUN', 'The presence of harmful substances in the air, water or soil.', 'sự ô nhiễm', 'Air pollution is a serious problem in many large cities.', NULL, 0, 'ACTIVE'),
    ('eeecf134-1d07-52f3-950d-821f694a752a', 'e67eac82-c716-5454-94f6-0168b6c0c982', 'NOUN', 'The usual weather conditions of a particular region.', 'khí hậu', 'The climate in this region is warm and dry.', NULL, 0, 'ACTIVE'),
    ('767bee24-7acc-57d7-b3cb-f6c12d3f94a2', 'da11da2c-dba2-5eef-a9a2-f135a8b8d7bf', 'NOUN', 'An amount of gas or another substance released into the air.', 'khí thải', 'Carbon emissions from cars have risen sharply.', NULL, 0, 'ACTIVE'),
    ('3308e16b-813d-58c6-88c8-f28005e23b08', '037d31be-9efb-5a6c-af95-908663177efb', 'ADJECTIVE', 'Able to be replaced naturally, so that it never runs out.', 'có thể tái tạo', 'Many countries are investing in renewable energy.', NULL, 0, 'ACTIVE'),
    ('ca524558-cc39-5fe1-a282-7f0b855c65f6', '072b4c9d-bfac-5327-88e3-bc42f0d5bee6', 'NOUN', 'The protection of nature and natural resources.', 'sự bảo tồn', 'Wildlife conservation needs long-term funding.', NULL, 0, 'ACTIVE'),
    ('d5580270-892d-5a9c-abf7-58862e380ebe', 'da6919d9-f08b-5c9c-8ca8-a3e52b080b2f', 'NOUN', 'The natural home of an animal or plant.', 'môi trường sống', 'Deforestation destroys the habitat of many species.', NULL, 0, 'ACTIVE'),
    ('c36d9ceb-bde0-52c2-8938-8ac6da3b05d1', '8a181521-d5d9-5a5a-968b-9e7905a3e216', 'NOUN', 'The cutting down of large areas of forest.', 'nạn phá rừng', 'Deforestation contributes to climate change.', NULL, 0, 'ACTIVE'),
    ('b5d321d9-403b-53bb-9e39-851b5b3eb108', '5ee46db0-fa25-57b1-b780-f43c6d927f83', 'ADJECTIVE', 'Able to continue for a long time without harming the environment.', 'bền vững', 'Sustainable farming protects the soil for future generations.', NULL, 0, 'ACTIVE'),
    ('1ae8413a-2834-56b7-a770-589c20916096', 'ccd13c59-edd9-54bf-91e4-5669faf80126', 'NOUN', 'The situation in which a species no longer exists.', 'sự tuyệt chủng', 'Many large animals are close to extinction.', NULL, 0, 'ACTIVE'),
    ('5c73146d-0840-5f30-a7a2-e04ed0611b17', 'e6ab5424-381e-5a76-ae71-f8415af7d9f8', 'NOUN', 'All the living things in an area and the way they affect each other.', 'hệ sinh thái', 'Coral reefs are a fragile ecosystem.', NULL, 0, 'ACTIVE'),
    ('ca7c43b3-9e7f-5906-8f22-e11dee71c43f', '6908f55c-bb03-5159-b41f-7bd1b0b40d3c', 'NOUN', 'The variety of plant and animal life in a place.', 'đa dạng sinh học', 'The rainforest has remarkable biodiversity.', NULL, 0, 'ACTIVE'),
    ('75a1c020-7325-5100-bf5f-6d34b5e2e12e', '93dcaa33-069f-5e23-85b0-229da173f87a', 'NOUN', 'A fuel such as coal or oil that formed from ancient plants and animals.', 'nhiên liệu hóa thạch', 'Burning fossil fuels releases carbon dioxide.', NULL, 0, 'ACTIVE'),
    ('01dfbe2b-0808-5347-a71a-c15b7fa9f1c5', '558c1b9f-767e-5724-b471-387018085c18', 'NOUN', 'A long period with very little rain.', 'hạn hán', 'The drought destroyed most of the crops.', NULL, 0, 'ACTIVE'),
    ('7c6e9623-5103-541e-8457-bee99c96452c', 'e69ade14-61e0-5186-b156-78691d4891be', 'NOUN', 'A large amount of water covering land that is usually dry.', 'trận lũ', 'The flood forced hundreds of families to leave their homes.', NULL, 0, 'ACTIVE'),
    ('f381a7f7-3927-50d6-83cd-922972568df1', '2c5956d2-76ed-5d83-aecc-a2a6d7971ecc', 'VERB', 'To process used materials so that they can be used again.', 'tái chế', 'Students are encouraged to recycle paper and plastic.', NULL, 0, 'ACTIVE'),
    ('ea6fc87b-3be1-521b-83d1-bcfda3272687', 'd134a2e5-6512-5ce4-86e7-f16a8cca4ee2', 'NOUN', 'Material that is no longer needed and is thrown away.', 'rác thải', 'Food waste makes up a large share of household rubbish.', NULL, 0, 'ACTIVE'),
    ('69307a95-f96a-5858-a6a2-4606ad8b44ff', '38903a10-5181-5288-aa97-988b27a2c037', 'NOUN', 'A place where rubbish is buried in the ground.', 'bãi chôn lấp rác', 'Too much plastic ends up in landfill.', NULL, 0, 'ACTIVE'),
    ('ff619c27-5905-56b0-aef3-1a9454459b3d', '9f1b27b1-e81f-5d9f-8070-78e3f5511578', 'NOUN', 'A supply of something useful, such as water or minerals.', 'tài nguyên', 'Fresh water is a limited resource.', NULL, 0, 'ACTIVE'),
    ('440f16b0-0e90-5e5d-a2c6-1ea1896285f4', '861d3f9e-1655-5bdc-8160-d98fe49383f7', 'ADJECTIVE', 'At risk of disappearing completely.', 'có nguy cơ tuyệt chủng', 'The tiger is an endangered species.', NULL, 0, 'ACTIVE'),
    ('7da6184d-223c-509b-b6f6-ad6df91afe76', '74b984fd-f058-5358-8f59-7ac105dff99f', 'NOUN', 'The gradual rise in the temperature of the Earth.', 'sự nóng lên toàn cầu', 'Global warming is melting the polar ice caps.', NULL, 0, 'ACTIVE'),
    ('51f8d154-a269-5a6e-a66d-e0e88cb3d436', '911e2056-cf6b-5fc0-be5d-fdb0ead39a03', 'NOUN', 'The layer of gases around the Earth.', 'khí quyển', 'Greenhouse gases trap heat in the atmosphere.', NULL, 0, 'ACTIVE'),
    ('cca0c28a-e528-5703-9fd0-927b360fd197', '911e2056-cf6b-5fc0-be5d-fdb0ead39a03', 'NOUN', 'The feeling or mood of a place.', 'bầu không khí', 'The cafe has a relaxed atmosphere.', NULL, 1, 'ACTIVE'),
    ('558cf38d-f450-51cd-abdc-0e914ab4fd29', '8ec0d9d1-bd40-5ec6-9d68-372c14ca9ae5', 'VERB', 'To make something dirty or harmful by adding a substance to it.', 'làm nhiễm bẩn', 'Chemicals from the factory contaminated the river.', NULL, 0, 'ACTIVE'),
    ('698eeec0-6f90-59a2-b85c-15d25face9dc', 'f5306810-12c1-59b1-9100-4851038de013', 'VERB', 'To keep something in its original or good condition.', 'bảo tồn', 'The government wants to preserve the old forest.', NULL, 0, 'ACTIVE'),
    ('64078d5a-7826-5f79-ac4b-becd19b70503', '54a04122-dd58-59da-bb19-1a2c21885ebe', 'NOUN', 'The gradual wearing away of soil or rock by wind or water.', 'sự xói mòn', 'Planting trees helps to prevent soil erosion.', NULL, 0, 'ACTIVE'),
    ('4532ef0b-d73f-5306-a9b2-884876dc6d06', '6481490c-71ee-5237-8d79-bb4fa60b649d', 'NOUN', 'The amount of carbon dioxide produced by a person, group or activity.', 'dấu chân carbon', 'Cycling to work lowers your carbon footprint.', NULL, 0, 'ACTIVE'),
    ('fbf045e1-700a-5013-8c84-24613b7f07b0', '3c3c9d7e-bc32-5cfe-adbf-827bb9ae2b03', 'NOUN', 'Animals and plants that live in natural conditions.', 'động thực vật hoang dã', 'National parks protect wildlife from hunters.', NULL, 0, 'ACTIVE'),
    ('bc177d3d-1714-5144-bd27-e8af833267b8', '457eec10-03cd-5a69-96a8-6ae81871b5a9', 'ADJECTIVE', 'Dangerous, especially to health or safety.', 'nguy hiểm', 'Hazardous waste must be stored safely.', NULL, 0, 'ACTIVE'),
    ('0265d7dd-02d5-5072-8406-1ce8f1d8e65c', '81199ca6-7c60-59ea-b85d-d02b796f87f2', 'VERB', 'To make a determined effort to deal with a difficult problem.', 'giải quyết', 'Cities must tackle air pollution quickly.', NULL, 0, 'ACTIVE'),
    ('43e12e61-eca4-50a6-ac5a-3116ed5111f7', 'b784e08b-4cd8-59c2-83ac-43c9ce024142', 'NOUN', 'The subjects taught in a school or college.', 'chương trình học', 'The curriculum includes science, art and music.', NULL, 0, 'ACTIVE'),
    ('2db56b74-f88f-54fc-891e-03b708cd1fd1', 'db087b19-be5e-5dfb-9813-133665b58955', 'NOUN', 'Teaching, or the money paid for it.', 'học phí', 'Tuition fees rise every year at many universities.', NULL, 0, 'ACTIVE'),
