    ('9406549c-8e53-5770-88e3-a6464b781760', '727bcf69-0b71-58d3-b455-9e7b4075722b', 'NOUN', 'Money given to a student to pay for their studies.', 'học bổng', 'She won a scholarship to study in Canada.', NULL, 0, 'ACTIVE'),
