    ('e175f9c8-5ff4-5c2f-b9ad-6a21b8fc3fae', '9ca9dbc4-93e2-5b7b-910a-cace980ce28d', 'NOUN', 'A piece of work given to a student as part of a course.', 'bài tập được giao', 'The assignment must be handed in on Friday.', NULL, 0, 'ACTIVE'),
    ('4e4aca86-65a6-5250-a31a-9b4e5648b92a', 'f8dcbed0-319c-50fb-8008-1322e0b959d3', 'NOUN', 'A time or date by which something must be finished.', 'hạn chót', 'I missed the deadline for the application.', NULL, 0, 'ACTIVE'),
    ('c2fcea6c-3b64-5ba1-a5f3-e797835dad07', '01860b68-ff04-5e15-8090-d71db2da7810', 'ADJECTIVE', 'Relating to skills needed for a particular job.', 'thuộc về nghề nghiệp', 'Vocational training prepares students for work.', NULL, 0, 'ACTIVE'),
    ('f2b2eb30-0131-5f40-9f04-0b15bc2ef915', '74f4a3ae-04de-5f66-b71b-01f140a66f08', 'ADJECTIVE', 'Required by a rule or law.', 'bắt buộc', 'Education is compulsory until the age of sixteen.', NULL, 0, 'ACTIVE'),
    ('f27655bc-3c30-5589-a000-bc7ad5594054', '6992d09b-a146-5b49-a367-5dbc7c2d4e93', 'NOUN', 'An exam passed or a course completed that shows you can do something.', 'bằng cấp', 'You need a teaching qualification for this job.', NULL, 0, 'ACTIVE'),
    ('f07033c4-3ff1-5c1e-8e8f-3787f795dbb0', 'c36d272c-31df-56fb-bbc7-81887e2e85c3', 'NOUN', 'A student who is studying for a first degree.', 'sinh viên đại học', 'Most undergraduates live on campus in their first year.', NULL, 0, 'ACTIVE'),
    ('ef7eb18f-0531-5303-846c-23e28de0c884', '94ef032d-7484-57b6-ab46-10d4045e2119', 'NOUN', 'A list of the topics covered in a course.', 'đề cương môn học', 'The syllabus is available on the course website.', NULL, 0, 'ACTIVE'),
    ('a99ab976-678b-5351-b6f3-260aff7d47e9', '60b0c825-8b96-5091-a891-e3a449c84994', 'NOUN', 'A teacher who works with one student or a small group.', 'gia sư', 'My tutor gave me helpful feedback on my essay.', NULL, 0, 'ACTIVE'),
    ('26a6a5a6-7d6a-5856-8d80-2dca97f6941d', '1b5ca336-98c9-5e64-8264-6750f8970939', 'NOUN', 'The land and buildings of a university.', 'khuôn viên trường', 'The campus has a library, a gym and several cafes.', NULL, 0, 'ACTIVE'),
    ('fed718ba-45b4-5785-aa64-ccf67a6b165b', '782643c5-9783-52b2-837e-b933e32ea9bb', 'ADJECTIVE', 'Relating to education, especially at college or university.', 'thuộc về học thuật', 'Her academic results improved this year.', NULL, 0, 'ACTIVE'),
    ('cdb7715b-8263-52f8-947a-1b3f60c8bedd', 'f7d7e400-3a33-5531-8907-3f5e744ec5d5', 'NOUN', 'Copying someone else''s work and presenting it as your own.', 'đạo văn', 'Plagiarism can lead to a student being expelled.', NULL, 0, 'ACTIVE'),
    ('5c30701f-d0cd-5e57-b00d-299e350f9ce4', 'a67094b4-9ee3-5b30-843a-c71ef3083e78', 'NOUN', 'A judgement about the quality or level of someone''s work.', 'sự đánh giá', 'Continuous assessment reduces pressure at exam time.', NULL, 0, 'ACTIVE'),
    ('fd21f7f0-8dcf-5a3a-a0e1-5eb19317ff63', '0e342d09-164d-5edc-88c7-4922dcac8bb5', 'NOUN', 'The reason or desire that makes someone want to do something.', 'động lực', 'Praise from teachers increases students'' motivation.', NULL, 0, 'ACTIVE'),
    ('52693e2a-4112-585d-a369-bc3370ba23fd', '1569f886-d578-5b98-a35e-fedd5bebe8e3', 'NOUN', 'A child who attends school.', 'học sinh', 'Each pupil receives a free textbook.', NULL, 0, 'ACTIVE'),
    ('7d81d70b-852f-561b-8480-4f3d12419c97', 'defe8b2f-3eda-5760-ba92-ca53fe1f51a4', 'NOUN', 'A long piece of writing for a university degree.', 'luận văn', 'He is writing a dissertation on urban planning.', NULL, 0, 'ACTIVE'),
