    ('390f84da-5abe-5a92-8c90-0d67da8b6c92', '516d2ef7-bded-5899-92a5-b4f57601628b', 'NOUN', 'A person of the same age or status as you.', 'bạn đồng trang lứa', 'Teenagers are strongly influenced by their peers.', NULL, 0, 'ACTIVE'),
    ('cf204c54-c405-5d5a-aabe-a5d041c0a5b8', '3e462b1a-726d-53d2-9619-5a6486bab211', 'ADJECTIVE', 'Done outside the normal school timetable.', 'ngoại khóa', 'Sport is the most popular extracurricular activity.', NULL, 0, 'ACTIVE'),
    ('fe53ff17-3e29-5abb-8e06-8911edebd112', '1928c090-30fc-5440-86cb-f24fde0efc01', 'NOUN', 'A way of studying in which students learn away from the school or university.', 'học từ xa', 'Distance learning allows people to study while working.', NULL, 0, 'ACTIVE'),
    ('c1fbd715-5dd0-509b-aa17-a82d584aadef', 'a7fcce2f-65d3-5ed1-a674-2d2626deb134', 'VERB', 'To study again what you have learned before an exam.', 'ôn tập', 'I need to revise for my history test.', NULL, 0, 'ACTIVE'),
