    ('9459230d-63a4-598f-9667-79a5b32710a6', '358e8098-db08-5189-8cb8-06181d47b74f', 'ADJECTIVE', 'Able to speak two languages well.', 'song ngữ', 'Bilingual children often switch easily between languages.', NULL, 0, 'ACTIVE'),
    ('859556b5-2609-56d5-8b5b-f4032af0d819', '402c4ee4-38f4-5025-90ce-f16ba24374a8', 'NOUN', 'A new idea, method or invention.', 'sự đổi mới', 'Technological innovation has changed the way we work.', NULL, 0, 'ACTIVE'),
    ('5ca2b2b9-deb8-57f0-b6e0-5d96c97451ee', '13a1295a-5d24-51e4-a8a1-b9469605de5d', 'NOUN', 'The use of machines to do work without human control.', 'tự động hóa', 'Automation has reduced the need for factory workers.', NULL, 0, 'ACTIVE'),
    ('6c0049e4-06ce-5a5d-9481-76b8301e2ec0', '9704f932-aa88-52e2-bacb-c603a718d45b', 'NOUN', 'Computer systems that can do tasks that normally need human thinking.', 'trí tuệ nhân tạo', 'Artificial intelligence is used to detect diseases early.', NULL, 0, 'ACTIVE'),
    ('d2a6859a-2c36-5407-ba87-6bd77cb92a62', '63a37570-b6e9-539f-8e96-a37e541c398c', 'NOUN', 'A set of rules that a computer follows to solve a problem.', 'thuật toán', 'The algorithm recommends videos based on what you watch.', NULL, 0, 'ACTIVE'),
    ('9cc0c962-8e59-50f0-8655-5e5efcbc90cb', '23a0c513-37d8-53eb-a297-2e99e75cce0c', 'ADJECTIVE', 'Using or storing information as numbers on computers.', 'kỹ thuật số', 'Digital cameras have replaced film cameras.', NULL, 0, 'ACTIVE'),
    ('b8e49cdd-930b-5808-b496-1201a64ab97d', 'c066e7f9-c417-5fbe-9250-d10f7070837e', 'NOUN', 'A small machine made for a particular purpose.', 'thiết bị', 'Most people carry at least one electronic device.', NULL, 0, 'ACTIVE'),
    ('f1b88013-55c9-5de5-bc96-fdc39c2aeb24', '3e359de0-01ec-5037-89b9-faa04e252ad9', 'NOUN', 'Programs that run on a computer.', 'phần mềm', 'The company sells accounting software to small businesses.', NULL, 0, 'ACTIVE'),
    ('5b20b689-bcc3-5e77-9f5d-7a7cf86c6926', '6337f13c-7fd9-5fed-bcdf-06a2652201d4', 'NOUN', 'Protection of computer systems from attack or theft.', 'an ninh mạng', 'Banks spend millions on cybersecurity.', NULL, 0, 'ACTIVE'),
